/* Tables are initialised to their declared fill.  A zero-filled calibration
 * table is not conservative, it is broken: it commands no air, so no fuel. */
#define RC_DEF_FUEL_VE_TABLE_FILL 70
static void rc_cal_fill_fuel_ve_table(rc_cal_t *image)
{
    for (uint32_t i = 0u; i < 256u; ++i) {
        image->fuel_ve_table_cells[i] = RC_DEF_FUEL_VE_TABLE_FILL;
    }
}

